/**
 * Real game data snapshot (agents, abilities, maps, callouts) from valorant-api.com.
 * Generated by scripts/fetch-game-data.mjs — do not edit the JSON files by hand.
 * See docs/data.md.
 */
import type { MapName, Role } from '../../engine/types';
import agentsJson from './agents.json';
import mapsJson from './maps.json';

/** API ability slots. Keybinds: Grenade = C, Ability1 = Q, Ability2 = E, Ultimate = X. */
export type AbilitySlot = 'Grenade' | 'Ability1' | 'Ability2' | 'Ultimate' | 'Passive';

export interface GameAbility {
  slot: AbilitySlot;
  /** English name. */
  name: string;
  /** pt-BR name. */
  displayName: string;
  /** Icon URL (Riot asset served by valorant-api.com); some passives have none. */
  displayIcon: string | null;
}

export interface GameAgent {
  uuid: string;
  /** English name (stable identifier used across the codebase). */
  name: string;
  /** pt-BR display name. */
  displayName: string;
  role: Role;
  /** pt-BR role name, e.g. "Controlador". */
  roleDisplayName: string;
  /** pt-BR short bio. */
  description: string;
  displayIcon: string;
  /** Ordered C, Q, E, X, then passive (if any). */
  abilities: GameAbility[];
}

export interface Callout {
  /** pt-BR region name, e.g. "Árvore". */
  regionName: string;
  /** pt-BR super region, e.g. "A", "Meio", "no Lado Atacante". */
  superRegionName: string;
  /** English region name, e.g. "Tree" (the callout pros actually use). */
  regionNameEn: string;
  /** English super region, e.g. "A", "Mid", "Attacker Side". */
  superRegionNameEn: string;
  /** Game world location (Unreal units). Use `calloutToMinimap` for minimap coords. */
  location: { x: number; y: number };
}

export interface GameMap {
  uuid: string;
  /** English name, matches `MapName` used by the engine (e.g. 'Ascent'). */
  name: MapName;
  /** pt-BR display name. */
  displayName: string;
  coordinates: string | null;
  /** Minimap image URL. */
  displayIcon: string;
  splash: string;
  xMultiplier: number;
  yMultiplier: number;
  xScalarToAdd: number;
  yScalarToAdd: number;
  callouts: Callout[];
}

/** Playable agents, sorted by English name. */
export const AGENTS: readonly GameAgent[] = agentsJson as GameAgent[];

/** Standard competitive maps (with sites and callouts), sorted by English name. */
export const MAPS: readonly GameMap[] = mapsJson as GameMap[];

const norm = (s: string) => s.trim().toLowerCase();

/** Finds an agent by English or pt-BR name (case-insensitive). */
export function agentByName(name: string): GameAgent | undefined {
  const n = norm(name);
  return AGENTS.find((a) => norm(a.name) === n || norm(a.displayName) === n);
}

/** Finds a map by English or pt-BR name (case-insensitive). */
export function mapByName(name: string): GameMap | undefined {
  const n = norm(name);
  return MAPS.find((m) => norm(m.name) === n || norm(m.displayName) === n);
}

/**
 * Converts a callout's world location to normalized minimap coordinates in [0, 1]
 * (origin at the top-left of the map's `displayIcon` image; multiply by the image size for pixels).
 *
 * Per the valorant-api.com convention, the world axes are swapped relative to the image:
 * the image's horizontal axis uses world Y and the vertical axis uses world X:
 *   x = location.y * xMultiplier + xScalarToAdd
 *   y = location.x * yMultiplier + yScalarToAdd
 * Verified by game.test.ts: with this formula every callout lands inside [0, 1]; the unswapped
 * variant falls outside the image for most maps.
 */
export function calloutToMinimap(map: GameMap, callout: Pick<Callout, 'location'>): { x: number; y: number } {
  return {
    x: callout.location.y * map.xMultiplier + map.xScalarToAdd,
    y: callout.location.x * map.yMultiplier + map.yScalarToAdd,
  };
}
